unts","definition_sha256":"b5b1d13295d7482625fbfc26d0d16e5c1c29b4c76014667aa640f621c42e21fb"},{"name":"identities_pkey","ready":true,"valid":true,"unique":true,"primary":true,"relation":"public.identities","definition_sha256":"d0bedd5f044bda88652e61e3b4763ee1110b40c9474136e79a1ffa40ea1aa54f"},{"name":"identity_profiles_identity_id_key","ready":true,"valid":true,"unique":true,"primary":false,"relation":"public.identity_profiles","definition_sha256":"3b164f7cc1947884b1e1f2ad2ae562b066757df3308e106eeb095b43d99f23c6"},{"name":"identity_profiles_slug_key","ready":true,"valid":true,"unique":true,"primary":false,"relation":"public.identity_profiles","definition_sha256":"6a4557f28f65d55480535a9515d59f82f00adf3d3e900220b1ab5f136da8b2d0"},{"name":"profiles_pkey","ready":true,"valid":true,"unique":true,"primary":true,"relation":"public.profiles","definition_sha256":"248eaa8d9ad55df13054ec6dad3a08495c4ae6534cad1099eea8e223f80d8c7d"},{"name":"profiles_store_slug_key","ready":true,"valid":true,"unique":true,"primary":false,"relation":"public.profiles","definition_sha256":"1217a464d265ef42290e64049a338a98ce135159eae44ac0be2d843240fd025b"}]}}'::jsonb b, '{"functions":[{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"body":"c4d0dce614f6a666a6867444b8b7c3a5c61ee1fa9a63a436c47cf40e84b2e4a4","owner":"postgres","config":["search_path=pg_catalog, pg_temp","TimeZone=UTC","lock_timeout=2s"],"result":"jsonb","strict":false,"definer":true,"defaults":null,"language":"plpgsql","parallel":"u","arguments":["p_user","p_identity","p_key","p_operation","p_request"],"leakproof":false,"signature":"jobs_private.mutate(uuid,uuid,uuid,text,jsonb)","volatility":"v"}],"helper_app_denied":true}'::jsonb before_t, '{"functions":[{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"body":"326ee6f4270f0032ccc4e80a7e4e2a528b19262b5f04c25bbc8ec801bbb0f678","owner":"postgres","config":["search_path=pg_catalog, pg_temp","TimeZone